harness:
#include <iostream>

struct Node
{
    int value;
    Node* next;
};

Node* ReverseList(Node* head);

int main()
{
    int n;
    while (std::cin >> n)
    {
        Node* head = nullptr;
        Node* tail = nullptr;
        for (int i = 0; i < n; i++)
        {
            int v;
            std::cin >> v;
            Node* node = new Node{v, nullptr};
            if (tail == nullptr)
            {
                head = tail = node;
            }
            else
            {
                tail->next = node;
                tail = node;
            }
        }

        Node* reversed = ReverseList(head);
        bool first = true;
        for (Node* cur = reversed; cur != nullptr; cur = cur->next)
        {
            if (!first) { std::cout << " "; }
            std::cout << cur->value;
            first = false;
        }
        std::cout << "\n";
    }
    return 0;
}

