"""Random-length lists of random values, including empty and single-node
ones."""


def generate(rng, count):
    return [_case(rng, i + 1) for i in range(count)]


def _case(rng, index):
    n = rng.randint(0, 12)
    values = [rng.randint(-50, 50) for _ in range(n)]
    lines = [str(n)] + [str(v) for v in values]
    return {"name": "a %d-node list #%d" % (n, index),
            "stdin": " ".join(lines) + "\n"}
